<?php
$e=static fn($v)=>esc((string)$v);
$batchBy=[]; foreach($d['batches'] as $b) $batchBy[$b['id']]=$b;
$reqBy=[]; foreach($d['requests'] as $r) $reqBy[$r['id']]=$r;
$totalExpected=array_sum(array_column($d['plans'],'qty')); $totalActual=array_sum(array_column($d['batches'],'received')); $totalHeld=array_sum(array_column($d['batches'],'held')); $available=0;
foreach($d['batches'] as $b) $available+=max(0,$b['cleared']-$b['reserved']);
$form=static function($type,$tab,$label){ echo '<form method="post" action="/action" class="form"><input type="hidden" name="'.csrf_token().'" value="'.csrf_hash().'"><input type="hidden" name="type" value="'.$type.'"><input type="hidden" name="tab" value="'.$tab.'"><h3>'.$label.'</h3>'; };
$end=static fn()=>print('</form>');
$select=static function($name,$rows,$label){ echo '<label>'.$label.'<select name="'.$name.'">'; foreach($rows as $r) echo '<option value="'.esc($r['id']).'">'.esc($r['id'].' · '.($r['coop']??$r['buyer']??$r['issue']??'')).'</option>'; echo '</select></label>'; };
$input=static function($name,$label,$type='text',$value='',$extra=''){ echo '<label>'.$label.'<input name="'.$name.'" type="'.$type.'" value="'.esc((string)$value).'" '.$extra.'></label>'; };
$button=static fn($label)=>print('<button type="submit">'.$label.' →</button>');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AgriSuri · Value chain simulation</title><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap');
:root{--green:#174d3b;--lime:#d9e8b3;--bg:#f5f6f1;--ink:#17231c;--muted:#647269;--line:#dce3d8;--card:#fff;--warn:#a86124}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:'DM Sans',sans-serif}h1,h2,h3{font-family:Outfit,sans-serif;margin:0}h1{font-size:34px;letter-spacing:-1.4px}h2{font-size:23px;margin-bottom:16px}h3{font-size:18px}p{line-height:1.55}a{color:inherit;text-decoration:none}.shell{display:flex;min-height:100vh}.side{width:240px;background:var(--green);color:white;padding:27px 17px;flex-shrink:0}.brand{padding:2px 15px 25px;font-family:Outfit;font-size:25px;font-weight:800;letter-spacing:-.8px}.brand span{color:#d8eeb6}.side small{display:block;color:#b7d4c1;text-transform:uppercase;letter-spacing:1.5px;font-size:10px;margin:12px 15px}.nav{display:block;padding:12px 15px;border-radius:10px;margin:4px 0;font-weight:600;font-size:14px;color:#d6e8dc}.nav:hover,.nav.active{background:#326b51;color:white}.main{padding:36px 44px;width:100%;max-width:1500px;margin:auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:28px}.eyebrow{color:#688071;text-transform:uppercase;letter-spacing:1.7px;font-weight:700;font-size:11px;margin-bottom:8px}.subtitle{color:var(--muted);margin:8px 0 0}.pill{display:inline-block;background:#e7f0dc;color:#356043;border-radius:20px;padding:6px 11px;font-size:12px;font-weight:700}.pill.amber{background:#fff0d9;color:#9a5f23}.pill.blue{background:#e5edf8;color:#335f89}.card{background:var(--card);border:1px solid var(--line);border-radius:17px;padding:22px;box-shadow:0 8px 25px #17352408}.grid{display:grid;gap:18px}.stats{grid-template-columns:repeat(4,1fr)}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.stat strong{display:block;font:700 28px Outfit;margin-top:9px}.muted{color:var(--muted);font-size:13px}.section{margin-top:28px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:14px}.flow{display:flex;gap:7px;flex-wrap:wrap}.flow span{background:#e9eee7;border-radius:7px;padding:9px;font-size:12px;font-weight:700}.flow i{align-self:center;color:#95a597}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;color:#728176;font-size:11px;text-transform:uppercase;letter-spacing:1px}th,td{padding:13px 11px;border-bottom:1px solid #edf0eb;vertical-align:top}tr:last-child td{border:0}td strong{font-weight:700}.form{background:white;border:1px solid var(--line);border-radius:17px;padding:22px;display:grid;gap:14px;align-content:start}.form h3{margin-bottom:3px}.form label{display:grid;gap:6px;font-size:12px;font-weight:700;color:#516458}.form input,.form select,.form textarea{width:100%;border:1px solid #d6dfd5;border-radius:9px;padding:10px 11px;font:inherit;color:var(--ink);background:white}.form textarea{min-height:70px}button{border:0;border-radius:9px;background:var(--green);color:white;padding:11px 15px;font-weight:700;cursor:pointer}button:hover{background:#287050}.reset{background:#e7eee7;color:var(--green)}.notice{padding:13px 17px;border-radius:10px;background:#e9f4e7;margin-bottom:18px}.notice.error{background:#fff0e6;color:#a4521c}.note{background:#f5f7f1;border-left:3px solid #a5bd8e;padding:13px 15px;border-radius:7px;color:#526557;font-size:13px;line-height:1.5}.option{border:1px solid var(--line);border-radius:12px;padding:17px}.option h3{margin-bottom:7px}.option p{font-size:13px;color:var(--muted);margin:6px 0}.list{padding-left:20px;line-height:1.8}.foot{margin-top:35px;color:#829084;font-size:12px}@media(max-width:1000px){.stats,.three{grid-template-columns:repeat(2,1fr)}}@media(max-width:750px){.shell{display:block}.side{width:auto;padding:14px;display:flex;overflow:auto;gap:5px;align-items:center}.brand{padding:5px 12px;white-space:nowrap}.side small{display:none}.nav{white-space:nowrap}.main{padding:24px 18px}.stats,.two,.three{grid-template-columns:1fr}.top{display:block}}
</style></head><body><div class="shell"><aside class="side"><div class="brand">Agri<span>Suri</span></div><small>AgriCoop Ph pilot</small><?php foreach(['overview'=>'Overview','supply'=>'Supply & batches','matching'=>'Buyer matching','analysis'=>'Value chain analysis','interventions'=>'Interventions','fulfillment'=>'Fulfillment','roadmap'=>'System scope'] as $key=>$label): ?><a class="nav <?= $tab===$key?'active':'' ?>" href="/?tab=<?= $key ?>"><?= $label ?></a><?php endforeach ?></aside><main class="main"><div class="top"><div><div class="eyebrow">Rice pilot · interactive simulation</div><h1><?= $e(['overview'=>'From harvest to buyer outcome','supply'=>'Supply & batches','matching'=>'Buyer matching','analysis'=>'Value chain analysis','interventions'=>'Intervention decisions','fulfillment'=>'Fulfillment & feedback','roadmap'=>'Whole-system scope'][$tab]??'AgriSuri') ?></h1><p class="subtitle">A traceable workflow for AgriCoop officers, cooperative representatives, and managers.</p></div><span class="pill">Demo data · Milled rice</span></div><?php if($message): ?><div class="notice"><?= $e($message) ?></div><?php endif ?><?php if($error): ?><div class="notice error"><?= $e($error) ?></div><?php endif ?>
<?php if($tab==='overview'): ?>
<div class="grid stats"><div class="card stat"><span class="muted">Expected harvest</span><strong><?= $e($totalExpected) ?> kg</strong><span class="pill blue">Plan only</span></div><div class="card stat"><span class="muted">Actual received</span><strong><?= $e($totalActual) ?> kg</strong><span class="muted">Confirmed batches</span></div><div class="card stat"><span class="muted">Cleared, unreserved</span><strong><?= $e($available) ?> kg</strong><span class="pill">Eligible by quality</span></div><div class="card stat"><span class="muted">Quality hold</span><strong><?= $e($totalHeld) ?> kg</strong><span class="pill amber">Not offerable</span></div></div>
<div class="section card"><div class="section-head"><h2>One connected process</h2><span class="muted">Start with the sample case or enter your own records</span></div><div class="flow"><?php foreach(['Harvest plan','Actual batch','Inspection','Buyer request','Match & gap','Intervention','Reservation','Delivery & outcome'] as $i=>$s): ?><?= $i?'<i>→</i>':'' ?><span><?= $s ?></span><?php endforeach ?></div><p class="note">The demonstration begins with 1,000 kg expected, 900 kg received, 100 kg held, 800 kg cleared, and 400 kg packaged. A buyer needs 600 kg packaged. The 200 kg packaging gap leads to an intervention decision.</p></div>
<div class="section grid two"><div class="card"><h2>Needs attention</h2><?php foreach($d['cases'] as $c): ?><p><strong><?= $e($c['id']) ?> · <?= $e($c['issue']) ?></strong><br><span class="muted"><?= $e($c['action'] ? 'Approved: '.$c['action'] : 'Awaiting manager decision') ?></span></p><?php endforeach ?></div><div class="card"><h2>Recent activity</h2><?php foreach(array_slice(array_reverse($d['events']),0,5) as $event): ?><p><span class="muted"><?= $e($event['time']) ?></span><br><?= $e($event['text']) ?></p><?php endforeach ?></div></div>
<?php elseif($tab==='supply'): ?>
<div class="grid two"><?php $form('plan','supply','1. Submit harvest plan'); $input('coop','Member cooperative'); $input('qty','Expected quantity (kg)','number','','min="1" required'); $input('date','Expected harvest date','date','','required'); $button('Add expected supply'); $end(); $form('batch','supply','2. Confirm actual harvest / receipt'); $select('plan',$d['plans'],'Linked harvest plan'); $input('qty','Actual received (kg)','number','','min="1" required'); $button('Create traceable batch'); $end(); ?></div>
<div class="section grid two"><?php $form('inspect','supply','3. Record inspection'); $select('batch',$d['batches'],'Batch'); $input('cleared','Cleared (kg)','number',800,'min="0" required'); $input('held','Held / rejected (kg)','number',100,'min="0" required'); $button('Save inspection'); $end(); $form('package','supply','4. Record packaging'); $select('batch',$d['batches'],'Batch'); $input('qty','Newly packaged (kg)','number','','min="1" required'); $input('cost','Recorded cost (₱)','number',0,'min="0"'); $button('Update packaging'); $end(); ?></div>
<div class="section card"><h2>Harvest calendar · expected supply</h2><div class="table-wrap"><table><tr><th>Plan</th><th>Cooperative</th><th>Product / form</th><th>Expected</th><th>Date</th><th>Status</th></tr><?php foreach($d['plans'] as $h): ?><tr><td><strong><?= $e($h['id']) ?></strong></td><td><?= $e($h['coop']) ?></td><td>Milled rice</td><td><?= $e($h['qty']) ?> kg</td><td><?= $e($h['date']) ?></td><td><span class="pill blue">Estimated</span></td></tr><?php endforeach ?></table></div></div><div class="section card"><h2>Confirmed batches</h2><div class="table-wrap"><table><tr><th>Batch</th><th>Source</th><th>Received</th><th>Cleared</th><th>Held</th><th>Packaged</th><th>Reserved</th><th>Recorded cost</th></tr><?php foreach($d['batches'] as $b): ?><tr><td><strong><?= $e($b['id']) ?></strong></td><td><?= $e($b['coop']) ?></td><td><?= $e($b['received']) ?></td><td><?= $e($b['cleared']) ?></td><td><?= $e($b['held']) ?></td><td><?= $e($b['packaged']) ?></td><td><?= $e($b['reserved']) ?></td><td>₱<?= $e($b['cost']) ?></td></tr><?php endforeach ?></table></div></div>
<?php elseif($tab==='matching'): ?>
<div class="grid two"><?php $form('request','matching','Record a buyer requirement'); $input('buyer','Buyer'); $input('qty','Requested quantity (kg)','number','','min="1" required'); $input('deadline','Delivery deadline','date','','required'); $input('location','Delivery location'); ?><label>Packaging<select name="packaging"><option>Packaged</option><option>Unpackaged accepted</option></select></label><?php $button('Create request'); $end(); $form('reserve','matching','Confirm a reservation'); $select('request',$d['requests'],'Buyer request'); $select('batch',$d['batches'],'Confirmed batch'); $input('qty','Quantity to reserve (kg)','number','','min="1" required'); ?><p class="note">Only cleared stock that meets the packaging requirement can be reserved. Existing reservations reduce availability.</p><?php $button('Reserve eligible stock'); $end(); ?></div>
<div class="section card"><h2>Proposed matches</h2><div class="table-wrap"><table><tr><th>Request</th><th>Batch</th><th>Requested</th><th>Buyer-ready now</th><th>Gap</th><th>Assessment</th></tr><?php foreach($d['requests'] as $r): foreach($d['batches'] as $b): $ready=max(0,($r['packaging']==='Packaged'?$b['packaged']:$b['cleared'])-$b['reserved']); $gap=max(0,$r['qty']-$r['reserved']-$ready); ?><tr><td><strong><?= $e($r['id']) ?></strong><br><span class="muted"><?= $e($r['buyer']) ?> · due <?= $e($r['deadline']) ?></span></td><td><?= $e($b['id']) ?><br><span class="muted"><?= $e($b['coop']) ?></span></td><td><?= $e($r['qty']) ?> kg</td><td><?= $e($ready) ?> kg</td><td><?= $e($gap) ?> kg</td><td><span class="pill <?= $gap?'amber':'' ?>"><?= $gap?'Needs action':'Potentially ready' ?></span><br><span class="muted">Confirm grade, location, and delivery timing.</span></td></tr><?php endforeach; endforeach ?></table></div><p class="note">Matching is a proposal, not a sale. Expected harvest appears on the supply calendar but never counts as buyer-ready stock.</p></div>
<?php elseif($tab==='analysis'): ?>
<div class="grid three"><div class="card"><div class="eyebrow">Descriptive · what happened?</div><h2>Supply evidence</h2><?php foreach($d['batches'] as $b): $plan=null; foreach($d['plans'] as $h) if($h['id']===$b['plan']) $plan=$h; ?><p><strong><?= $e($b['id']) ?></strong>: <?= $e($b['received']) ?> kg received, <?= $e($b['held']) ?> kg held, <?= $e($b['cleared']) ?> kg cleared, <?= $e($b['packaged']) ?> kg packaged.</p><?php if($plan): ?><p class="muted">Harvest variance: <?= $e($b['received']-$plan['qty']) ?> kg against <?= $e($plan['qty']) ?> kg expected.</p><?php endif; endforeach ?></div><div class="card"><div class="eyebrow">Predictive · what might happen?</div><h2>Rule-based scenario</h2><?php $r=$d['requests'][0]; $b=$d['batches'][0]; $days=max(0,(int)ceil((strtotime($r['deadline'])-time())/86400)); $scenario=min($b['cleared'],$b['packaged']+100*$days); ?><p>At an assumed <strong>100 kg/day</strong> packaging rate, up to <strong><?= $e($scenario) ?> kg</strong> could be ready by <?= $e($r['deadline']) ?>.</p><p class="muted">This is a scenario, not a validated forecast or confirmed capacity. Staff must verify the packaging schedule.</p></div><div class="card"><div class="eyebrow">Prescriptive · what can we do?</div><h2>Compare responses</h2><p>Package cleared stock, source another eligible batch, or request a buyer-approved date change.</p><p class="muted">See cost, conditions, and an approval task under Interventions.</p></div></div>
<div class="section card"><h2>Buyer outcomes</h2><?php foreach($d['requests'] as $r): ?><p><strong><?= $e($r['id']) ?></strong> · <?= $e($r['accepted']) ?> / <?= $e($r['qty']) ?> kg accepted (<?= $r['qty']?round(100*$r['accepted']/$r['qty']):0 ?>% fulfillment). <?= $e($r['rejected']) ?> kg rejected or returned.</p><?php endforeach ?><p class="note">Costs shown are recorded batch costs only. This simulation does not calculate profit from incomplete cost data.</p></div>
<?php elseif($tab==='interventions'): ?>
<div class="grid three"><div class="option card"><h3>Package the gap</h3><p>Uses cleared, unpackaged stock from the same cooperative.</p><p><strong>Verify:</strong> packaging capacity and completion date.</p><p><strong>Trade-off:</strong> added packaging cost; deadline risk.</p></div><div class="option card"><h3>Source eligible stock</h3><p>Find another confirmed, inspected, unreserved batch.</p><p><strong>Verify:</strong> grade, packaging, location, and availability.</p><p><strong>Trade-off:</strong> possible transport cost.</p></div><div class="option card"><h3>Request a new date</h3><p>Discuss a revised deadline with the buyer.</p><p><strong>Verify:</strong> buyer agreement before changing terms.</p><p><strong>Trade-off:</strong> buyer may decline.</p></div></div>
<div class="section card"><h2>Evidence-based cases</h2><?php foreach($d['cases'] as $c): ?><p><strong><?= $e($c['id']) ?> · <?= $e($c['issue']) ?></strong><br><span class="muted">Linked <?= $e($c['batch']) ?> / <?= $e($c['request']) ?> · <?= $e($c['evidence']) ?></span><br><span class="pill <?= $c['action']?'':'amber' ?>"><?= $e($c['action'] ?: 'Needs manager decision') ?></span> <?= $c['owner']?'Owner: '.$e($c['owner']).' · Due '.$e($c['due']):'' ?> <?= $c['outcome']?' · Result: '.$e($c['outcome']):'' ?></p><?php endforeach ?></div>
<div class="section grid three"><?php $form('case','interventions','Open an observed issue'); $select('request',$d['requests'],'Request'); $select('batch',$d['batches'],'Batch'); $input('issue','Observed gap','','','required'); ?><label>Linked evidence<textarea name="evidence" placeholder="Cite batch and request facts"></textarea></label><?php $button('Open case'); $end(); $form('approve','interventions','Manager: approve action'); $select('case',$d['cases'],'Case'); ?><label>Selected action<select name="action"><option>Package cleared stock</option><option>Source eligible batch</option><option>Request buyer date change</option></select></label><?php $input('owner','Responsible person','','','required'); $input('due','Task deadline','date','','required'); $input('estimate','Estimated extra cost (₱)','number',0,'min="0"'); $button('Approve & assign'); $end(); $form('outcome','interventions','Record intervention outcome'); $select('case',$d['cases'],'Case'); ?><label>Observed result<textarea name="outcome" required placeholder="What was completed, and did it help?"></textarea></label><?php $input('actual','Actual recorded cost (₱)','number',0,'min="0"'); $button('Record outcome'); $end(); ?></div>
<?php elseif($tab==='fulfillment'): ?>
<div class="grid two"><?php $form('delivery','fulfillment','Record dispatch & buyer feedback'); $select('request',$d['requests'],'Buyer request'); $input('sent','Dispatched (kg)','number','','min="1" required'); $input('accepted','Accepted by buyer (kg)','number',0,'min="0" required'); $input('rejected','Rejected / returned (kg)','number',0,'min="0" required'); $input('price','Agreed price per kg (₱)','number',0,'min="0"'); ?><label>Payment status<select name="payment"><option>Unpaid</option><option>Partial</option><option>Paid</option></select></label><?php $button('Save buyer outcome'); $end(); ?><div class="card"><h2>Sales & delivery records</h2><div class="table-wrap"><table><tr><th>Request</th><th>Reserved</th><th>Sent</th><th>Accepted</th><th>Rejected</th><th>Payment</th></tr><?php foreach($d['requests'] as $r): ?><tr><td><?= $e($r['id']) ?></td><td><?= $e($r['reserved']) ?></td><td><?= $e($r['sent']) ?></td><td><?= $e($r['accepted']) ?></td><td><?= $e($r['rejected']) ?></td><td><?= $e($r['payment']) ?></td></tr><?php endforeach ?></table></div><p class="note">Buyer rejection records an observed problem. Staff investigates the cause and can open a linked intervention case.</p></div></div>
<?php else: ?>
<div class="grid two"><div class="card"><h2>What this simulation covers</h2><ul class="list"><li>Harvest plans remain estimated until an actual batch is recorded.</li><li>Inspection separates cleared and held stock.</li><li>Packaging and reservations update buyer-ready quantities.</li><li>Buyer requests show explainable gaps and proposed matches.</li><li>Managers compare actions and record approval, owner, deadline, and outcome.</li><li>Delivery acceptance and payment status support outcome review.</li><li>Event history records simulation changes.</li></ul></div><div class="card"><h2>Planned for the full system</h2><ul class="list"><li>Account login and cooperative-specific permissions; buyer and partner access if adopted.</li><li>Verified record corrections with complete audit history and evidence attachments.</li><li>AI-assisted English/Taglish draft entry and linked case summaries, each requiring staff review.</li><li>Reminders, notifications, and task completion tracking.</li><li>Storage movements, detailed logistics, invoices, returns, and multi-batch allocation.</li><li>Validated forecasts only after enough historical cases exist; optional satellite risk signals if reliable farm data is available.</li></ul></div></div><div class="section card"><h2>Pilot validation needed</h2><p>Confirm the pilot product and stages with AgriCoop, obtain five de-identified completed cases, and agree on buyer standards, batch IDs, responsible staff, realistic interventions, and available cost records.</p><p class="note">This is a workflow simulation using sample rice data. It does not represent live cooperative stock or buyer commitments.</p><?php $form('reset','roadmap','Restart demonstration'); $button('Reset sample records'); $end(); ?></div>
<?php endif ?><div class="foot">AgriSuri · AgriCoop Ph pilot concept · All figures in this simulation are sample data.</div></main></div></body></html>
